import json

with open('inventory.json') as f:
    counts = json.load(f)

with open('transactions.txt') as f:
    lines = f.read().splitlines()

rejected = []
for n, line in enumerate(lines, 1):
    parts = line.split()
    if not parts:
        continue
    if len(parts) != 3:
        rejected.append(n)
        continue
    op, sku, qty_s = parts
    try:
        qty = int(qty_s)
    except ValueError:
        rejected.append(n)
        continue
    if qty < 0:
        rejected.append(n)
        continue
    if op == 'add':
        counts[sku] = counts.get(sku, 0) + qty
    elif op == 'remove':
        if sku not in counts or counts[sku] - qty < 0:
            rejected.append(n)
        else:
            counts[sku] -= qty
    else:
        rejected.append(n)

with open('inventory_after.json', 'w') as f:
    json.dump(counts, f, indent=2)
    f.write('\n')

with open('rejected.txt', 'w') as f:
    for n in rejected:
        f.write(str(n) + '\n')

print('lines:', len(lines), 'rejected:', len(rejected), 'skus:', len(counts))
